<style scoped lang="scss" src="./avatar-message.scss"></style>

<script lang="js">
import { Component, Prop, Vue } from "vue-property-decorator";
import { AvatarImageSize, AvatarImageSizeValues, AvatarFontSize, AvatarFontSizeValues } from "./avatar-message.constants.js";
import { has } from "../../util/has";

/**
 * Quick display of an avatar with their name or title along with a simple
 * message.
 */
@Component
export default class AvatarMessage extends Vue {
  @Prop({ type: String, default: "" }) image;
  @Prop({
    type: String,
    default: AvatarImageSize.SMALL,
    validator: has(AvatarImageSizeValues)
  }) imageSize;
  @Prop({
    type: String,
    default: AvatarFontSize.SMALL,
    validator: has(AvatarFontSizeValues)
  }) fontSize;
  @Prop({ type: String, default: "" }) title;
  @Prop({ type: String, default: "" }) message;

  get imageSizeClass() {
    return this.imageSize;
  }

  get fontSizeClass() {
    return this.fontSize;
  }

  get imageStyle() {
    return {
      backgroundImage: `url(${this.image})`
    }
  }


}
</script>

<template>
  <div class="AvatarMessage">
    <div
      :class="['AvatarMessage__Image', imageSizeClass]"
      :style="imageStyle"
    ></div>
    <div class="AvatarMessage__Text">
      <div
        v-if="Boolean(title)"
        :class="['AvatarMessage__Title', fontSizeClass]"
      >
        {{ title }}
      </div>
      <div
        v-if="Boolean(message)"
        :class="['AvatarMessage__Message', fontSizeClass]"
      >
        {{ this.message }}
      </div>
    </div>
  </div>
</template>
